<?php
declare(strict_types=1);require __DIR__.'/app/investment-participation.php';$user=require_verified();$id=investment_text($_GET,'id',36);$op=investable_opportunity($id);$profile=investor_profile($user);$scenarios=rows("SELECT * FROM investment_financial_scenarios WHERE opportunity_id=? ORDER BY FIELD(scenario_type,'DOWNSIDE','BASE','UPSIDE')",[$id]);$evidence=rows("SELECT evidence_type,evidence_strength,title,notes FROM investment_demand_evidence WHERE opportunity_id=? AND evidence_strength IN ('SOFT_INTEREST','VERIFIED_COMMERCIAL') ORDER BY evidence_strength DESC,created_at DESC",[$id]);$documents=rows("SELECT id,title,document_type FROM investment_opportunity_documents WHERE opportunity_id=? AND visibility='INVESTOR' ORDER BY created_at DESC",[$id]);$instruction=rows('SELECT * FROM investment_funding_instructions WHERE opportunity_id=? AND is_active=1',[$id])[0]??null;$saved=(bool)rows('SELECT 1 FROM investment_saved_opportunities WHERE user_id=? AND opportunity_id=?',[$user['id'],$id]);$followed=(bool)rows('SELECT 1 FROM investment_followed_opportunities WHERE user_id=? AND opportunity_id=?',[$user['id'],$id]);$target=(float)$op['target_funding_amount'];$progress=$target>0?min(100,(float)$op['confirmed_funding']/$target*100):0;$active='investment';$pageTitle=$op['title'];require __DIR__.'/includes/operations-header.php';?>
<link rel="stylesheet" href="assets/css/investment-market.css?v=<?= filemtime(APP_ROOT.'/assets/css/investment-market.css') ?>">
<article class="investment-public"><header class="investment-public-hero"><div><p class="investment-kicker">APPROVED EQUIPMENT OPPORTUNITY</p><h1><?= e($op['title']) ?></h1><p><?= e($op['opportunity_rationale']) ?></p><div><strong><?= e($op['organization_name']) ?></strong> · <?= e($op['target_geography']) ?> · <?= (int)$op['quantity'] ?> unit(s)</div></div><aside><small>Funding target</small><h2><?= e($op['currency']) ?> <?= number_format($target,2) ?></h2><div class="funding-progress"><span style="width:<?= $progress ?>%"></span></div><p><?= number_format($progress,1) ?>% confirmed</p><strong><?= e(str_replace('_',' ',$op['funding_status'])) ?></strong><form action="investment-participation-action" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($id) ?>"><button name="action" value="save"><?= $saved?'Saved':'Save' ?></button><button name="action" value="follow"><?= $followed?'Following':'Follow' ?></button></form></aside></header>
<nav class="investment-public-tabs"><a href="#overview">Overview</a><a href="#equipment">Equipment</a><a href="#demand">Demand</a><a href="#financials">Financials</a><a href="#deployment">Deployment</a><a href="#risk">Risk</a><a href="#documents">Documents</a></nav>
<div class="investment-public-grid"><main class="investment-public-main"><section id="overview"><h2>Overview</h2><dl><div><dt>Asset useful life / maximum term</dt><dd><?= number_format((int)$op['asset_useful_life_days']) ?> days</dd></div><div><dt>Minimum term</dt><dd><?= number_format((int)$op['minimum_term_days']) ?> days</dd></div><div><dt>Target term</dt><dd><?= number_format((int)$op['target_term_days']) ?> days · official agreement term for the planned sale</dd></div><div><dt>Minimum participation</dt><dd><?= e($op['currency']) ?> <?= number_format((float)$op['minimum_participation'],2) ?></dd></div><div><dt>Ownership vehicle</dt><dd><?= e($op['ownership_vehicle']) ?></dd></div><div><dt>Finance/Security Partner</dt><dd><?= e($op['finance_security_partner']) ?></dd></div></dl><p class="invest-warning">Participation represents economic rights in the Deal. It does not transfer legal title to the equipment. Projected returns are not guaranteed.</p></section><section id="equipment"><h2>Equipment</h2><p><?= nl2br(e($op['specification'])) ?></p><dl><div><dt>Type</dt><dd><?= e($op['equipment_type_name']?:'Not stated') ?></dd></div><div><dt>OEM / model</dt><dd><?= e(trim(($op['oem_name']??'').' '.($op['model_name']??''))?:'Not selected') ?></dd></div><div><dt>Condition</dt><dd><?= e($op['equipment_condition']) ?></dd></div><div><dt>Supplier</dt><dd><?= e($op['supplier_name']?:'Not disclosed') ?></dd></div></dl></section><section id="demand"><h2>Demand evidence</h2><?php foreach($evidence as $row):?><article><strong><?= e($row['title']) ?></strong><p><?= e(str_replace('_',' ',$row['evidence_strength'])) ?> · <?= e(str_replace('_',' ',$row['evidence_type'])) ?></p></article><?php endforeach;?><?php if(!$evidence):?><p>No investor-visible demand evidence supplied.</p><?php endif;?></section><section id="financials"><h2>Scenario financials</h2><p>These are modeled scenarios, not guaranteed outcomes.</p><dl><?php foreach($scenarios as $scenario):?><div><dt><?= e($scenario['scenario_type']) ?></dt><dd><?= $scenario['projected_return_percent']===null?'Not stated':number_format((float)$scenario['projected_return_percent'],2).'% projected' ?><br><?= e($scenario['currency']) ?> <?= number_format((float)$scenario['projected_revenue']) ?> revenue<br><?= number_format((float)$scenario['utilization_percent'],1) ?>% utilization</dd></div><?php endforeach;?></dl></section><section id="deployment"><h2>Deployment</h2><dl><div><dt>Target geography</dt><dd><?= e($op['target_geography']) ?></dd></div><div><dt>Deployment state</dt><dd><?= e($op['deployment_state']?:'Planned') ?></dd></div></dl></section><section id="risk"><h2>Principal risks and controls</h2><p><?= nl2br(e($op['primary_risks'])) ?></p><h3>Recovery rights</h3><p><?= nl2br(e($op['recovery_rights'])) ?></p><h3>Distribution waterfall</h3><p><?= nl2br(e($op['distribution_waterfall'])) ?></p></section><section id="documents"><h2>Authorized documents</h2><?php foreach($documents as $document):?><p><a href="investment-document?id=<?= e($document['id']) ?>" target="_blank"><?= e($document['title']) ?></a> · <?= e(str_replace('_',' ',$document['document_type'])) ?></p><?php endforeach;?></section></main>
<aside><section><h2>Participate</h2><?php if($profile['kyc_status']!=='VERIFIED'):?><p>Your investor profile must be verified before capital can be submitted.</p><a href="investor-profile">Complete investor profile</a><?php elseif($op['funding_status']!=='OPEN'):?><p>Funding is not currently open.</p><?php else:?><form class="participation-form" action="investment-participation-action" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="participate"><input type="hidden" name="id" value="<?= e($id) ?>"><label>Amount (<?= e($op['currency']) ?>)<input type="number" name="amount" min="<?= e((string)$op['minimum_participation']) ?>" step="0.01" required></label><label>Transfer/reference note<input name="investor_reference"></label><label>Signing name<input name="signature_name" value="<?= e($profile['legal_name']) ?>" required></label><label><input type="checkbox" name="projection_acknowledgement" value="1" required> I understand projections are not guaranteed.</label><label><input type="checkbox" name="risk_acknowledgement" value="1" required> I reviewed the risks and structure.</label><label><input type="checkbox" name="title_acknowledgement" value="1" required> I understand participation does not confer equipment title.</label><button class="invest-primary">Sign and submit contribution</button></form><?php endif;?></section><?php if($instruction&&$profile['kyc_status']==='VERIFIED'):?><section><h2>Authorized funding instructions</h2><p><?= e($instruction['finance_partner']) ?><br><?= e($instruction['bank_name']) ?><br><?= e($instruction['account_name']) ?><br><?= e($instruction['account_reference']) ?></p><small><?= nl2br(e($instruction['instructions'])) ?></small></section><?php endif;?></aside></div></article>
